/* Standalone test for libidn2 punycode_decode vulnerability */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/* Define the types and constants needed */
typedef uint32_t punycode_uint;

#define IDN2_OK 0
#define punycode_success IDN2_OK
#define punycode_overflow -204
#define punycode_big_output -203
#define punycode_bad_input -202

/* Copy the vulnerable puny_decode.c code directly */
enum { base = 36, tmin = 1, tmax = 26, skew = 38, damp = 700,
       initial_bias = 72, initial_n = 0x80, delimiter = 0x2D };

#define basic(cp) ((cp >= 'a' && cp <= 'z') || (cp >= '0' && cp <='9') || (cp >= 'A' && cp <='Z') || cp == '-' || cp == '_')
#define delim(cp) ((cp) == delimiter)

static unsigned decode_digit(int cp)
{
  if (cp >= 'a' && cp <= 'z') return cp - 'a';
  if (cp >= '0' && cp <= '9') return cp - '0' + 26;
  if (cp >= 'A' && cp <= 'Z') return cp - 'A';
  return 0;
}

static const punycode_uint maxint = -1;

static punycode_uint adapt(punycode_uint delta, punycode_uint numpoints, int firsttime)
{
  punycode_uint k;
  delta = firsttime ? delta / damp : delta >> 1;
  delta += delta / numpoints;
  for (k = 0; delta > ((base - tmin) * tmax) / 2; k += base) {
    delta /= base - tmin;
  }
  return k + (base - tmin + 1) * delta / (delta + skew);
}

int punycode_decode(
  size_t input_length,
  const char input[],
  size_t *output_length,
  punycode_uint output[])
{
  punycode_uint n, out, i, max_out, bias, oldi, w, k, digit, t;
  size_t b, j, in;

  n = initial_n;
  out = i = 0;
  max_out = *output_length > maxint ? maxint : (punycode_uint) *output_length;
  bias = initial_bias;

  for (b = j = 0; j < input_length; ++j) if (delim(input[j])) b = j;
  if (b >= max_out) return punycode_big_output;

  for (j = 0; j < b; ++j) {
    if (!basic(input[j])) return punycode_bad_input;
    output[out++] = input[j];
  }
  b += delim(input[b]);

  for (j = b; j < input_length; ++j)
    if (!basic(input[j])) return punycode_bad_input;

  for (in = b; in < input_length; ++out) {
    for (oldi = i, w = 1, k = base; ; k += base) {
      if (in >= input_length) return punycode_bad_input;
      digit = decode_digit(input[in++]);
      if (digit >= base) return punycode_bad_input;
      if (digit > (maxint - i) / w) return punycode_overflow;
      i += digit * w;
      t = k <= bias ? tmin : k >= bias + tmax ? tmax : k - bias;
      if (digit < t) break;
      if (w > maxint / (base - t)) return punycode_overflow;
      w *= (base - t);
    }

    bias = adapt(i - oldi, out + 1, oldi == 0);

    if (i / (out + 1) > maxint - n) return punycode_overflow;
    n += i / (out + 1);
    if (n > 0x10FFFF || (n >= 0xD800 && n <= 0xDBFF)) return punycode_bad_input;
    i %= (out + 1);

    if (out >= max_out) return punycode_big_output;

    memmove(output + i + 1, output + i, (out - i) * sizeof *output);
    output[i++] = n;
  }

  *output_length = (size_t) out;
  return punycode_success;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    char *input = malloc(size + 1);
    fread(input, 1, size, f);
    fclose(f);
    input[size] = 0;

    printf("Input (%ld bytes): ", size);
    for (long i = 0; i < size; i++) printf("%02x ", (unsigned char)input[i]);
    printf("\n");

    punycode_uint output[256];
    size_t output_length = 256;

    int rc = punycode_decode(size, input, &output_length, output);
    printf("Result: %d, output_length: %zu\n", rc, output_length);

    free(input);
    return 0;
}
